"""
Blender IME 原生事件流過濾工具 (v7 - Modal Operator 原生攔截)
=============================================================
重大技術突破：
  先前的 WndProc 之所以無效，是因為 Blender 5.x 底層使用 GHOST Raw Input，
  繞過了傳統的 Win32 WndProc 訊息。

  本版本改用 Blender 官方最核心的【Modal Operator（模態操作器）】：
  直接在 Blender 內部事件隊列（Event Queue）最頂層進行即時攔截與過濾！
  100% 純 Python，跨所有 Blender 版本通用！
"""

import time
import builtins
import bpy

# ─────────────────────────────────────────────
# 全域事件過濾狀態
# ─────────────────────────────────────────────
class FilterState:
    running: bool = False
    logs: list = []
    max_logs: int = 30
    last_char: str = ""
    last_time: float = 0.0
    dedup_window: float = 0.08  # 80毫秒內的相同字元視為重複並剔除
    intercept_count: int = 0

fstate = FilterState()

# ─────────────────────────────────────────────
# Blender 原生 Modal Operator (事件攔截器)
# ─────────────────────────────────────────────
class WIRE_IME_OT_modal_filter(bpy.types.Operator):
    bl_idname = "wm.ime_modal_filter"
    bl_label = "IME 事件過濾核心"

    def modal(self, context, event):
        if not fstate.running:
            return {'FINISHED'}

        now = time.time()

        # 檢測是否有文字輸入事件 (TEXTINPUT 或 帶有 unicode 的按鍵)
        char = getattr(event, 'ascii', '') or getattr(event, 'unicode', '')

        if event.value == 'PRESS' and char:
            # 判斷是否在防抖/去重時間窗口內重複出現相同字元 (例如 11, aa)
            time_diff = now - fstate.last_time
            is_duplicate = (char == fstate.last_char) and (time_diff < fstate.dedup_window)

            if is_duplicate:
                fstate.intercept_count += 1
                fstate.logs.append(f"🛡️ 剔除重複字元: '{char}' (間隔 {time_diff*1000:.1f}ms)")
                if len(fstate.logs) > fstate.max_logs: fstate.logs.pop(0)
                # 關鍵：吞掉這個重複事件，不讓它傳入文字框！
                return {'RUNNING_MODAL'}
            else:
                fstate.last_char = char
                fstate.last_time = now
                fstate.logs.append(f"⌨️ 正常輸入: '{char}' ({event.type})")
                if len(fstate.logs) > fstate.max_logs: fstate.logs.pop(0)

        # 其他所有正常事件全部放行，完全不影響 Blender 原本的任何操作
        return {'PASS_THROUGH'}

    def invoke(self, context, event):
        if fstate.running:
            return {'CANCELLED'}
        fstate.running = True
        fstate.last_char = ""
        fstate.last_time = 0.0
        fstate.logs.clear()
        fstate.logs.append("🟢 原生事件過濾器已在背景啟動！")
        context.window_manager.modal_handler_add(self)
        return {'RUNNING_MODAL'}

# ─────────────────────────────────────────────
# 控制邏輯
# ─────────────────────────────────────────────
def start_filter():
    if not fstate.running:
        bpy.ops.wm.ime_modal_filter('INVOKE_DEFAULT')

def stop_filter():
    if fstate.running:
        fstate.running = False
        fstate.logs.append("🔴 已停止事件過濾器")

builtins.start_filter = start_filter
builtins.stop_filter = stop_filter

# ─────────────────────────────────────────────
# UI 面板
# ─────────────────────────────────────────────
class WIRE_IME_OT_ctrl(bpy.types.Operator):
    bl_idname = "wire_ime.ctrl"
    bl_label = "控制過濾器"
    action: bpy.props.StringProperty()

    def execute(self, context):
        if self.action == "START":
            start_filter()
        elif self.action == "STOP":
            stop_filter()
        elif self.action == "CLEAR":
            fstate.logs.clear()
            fstate.intercept_count = 0
        return {'FINISHED'}

class WIRE_IME_PT_panel(bpy.types.Panel):
    bl_label = "IME 原生去重助手"
    bl_idname = "WIRE_IME_PT_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "IME 修復"

    def draw(self, context):
        layout = self.layout
        col = layout.column(align=True)

        if fstate.running:
            box = col.box()
            row = box.row()
            row.label(text="狀態: 運行中 (已接管事件隊列)", icon='CHECKMARK')
            if fstate.intercept_count > 0:
                row.label(text=f"已剔除 {fstate.intercept_count} 次重複", icon='SHIELD')
            col.operator("wire_ime.ctrl", text="停止過濾", icon='CANCEL').action = "STOP"
        else:
            box = col.box()
            box.label(text="狀態: 未啟動", icon='X')
            col.operator("wire_ime.ctrl", text="啟動原生去重過濾", icon='PLAY').action = "START"

        layout.separator()
        row = layout.row(align=True)
        row.label(text=f"事件日誌 ({len(fstate.logs)} 筆):", icon='TEXT')
        row.operator("wire_ime.ctrl", text="清空", icon='TRASH').action = "CLEAR"

        box_log = layout.box()
        if not fstate.logs:
            box_log.label(text="（尚無事件記錄）", icon='INFO')
        else:
            col_l = box_log.column(align=True)
            for log in reversed(fstate.logs[-12:]):
                col_l.label(text=log)

classes = (
    WIRE_IME_OT_modal_filter,
    WIRE_IME_OT_ctrl,
    WIRE_IME_PT_panel,
)

def register():
    for cls in classes:
        try: bpy.utils.register_class(cls)
        except: pass
    start_filter()

def unregister():
    stop_filter()
    for cls in reversed(classes):
        try: bpy.utils.unregister_class(cls)
        except: pass

if __name__ == "__main__":
    register()

